SET LOCAL ROLE corpus_sem_publisher;
-- Exact compact descriptor from canonical wire bytes, without a whole-envelope JSONB value.
CREATE OR REPLACE FUNCTION ops.pdf_product_descriptor(p_payload bytea) RETURNS jsonb
LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog,pg_temp AS $descriptor$
DECLARE result jsonb:='{}'; content_metadata jsonb:='{}'; field_name text; field_value json;
BEGIN
 FOR field_name,field_value IN SELECT key,value FROM json_each(convert_from(p_payload,'UTF8')::json) LOOP
  IF field_name='content' THEN
   SELECT COALESCE(jsonb_object_agg(key,value::jsonb),'{}'::jsonb) INTO content_metadata
    FROM json_each(field_value) WHERE key IN ('schema_digest','recipe_digest','health');
  ELSIF field_name<>ALL(ARRAY['occurrences','relations','coverage','inputs','mapping_reports']) THEN
   result:=result||jsonb_build_object(field_name,field_value::jsonb);
  END IF;
 END LOOP;
 IF result->>'kind'='integrated' THEN
  result:=result||jsonb_build_object('content_metadata',content_metadata);
 END IF;
 RETURN result;
END $descriptor$;
ALTER FUNCTION ops.pdf_product_descriptor(bytea) OWNER TO corpus_sem_publisher;
REVOKE ALL ON FUNCTION ops.pdf_product_descriptor(bytea) FROM PUBLIC;
DO $checks$ DECLARE n text; BEGIN FOR n IN SELECT conname FROM pg_constraint WHERE conrelid='ops.pdf_product_body'::regclass AND contype='c' LOOP EXECUTE format('ALTER TABLE ops.pdf_product_body DROP CONSTRAINT %I',n); END LOOP; END $checks$;
ALTER TABLE ops.pdf_product_body ADD CONSTRAINT ck_pdf_product_body_physical_acbf4a8f01 CHECK (descriptor = ops.pdf_product_descriptor(payload));
SET LOCAL ROLE corpus_sem_publisher;
CREATE OR REPLACE VIEW ops.pdf_selected_product AS SELECT task_id, product_key, content_digest, release_id, contract_digest, schema_digest, recipe_digest, parent_task_id, parent_product_key, parent_digest, native_json, health, payload FROM ops.native_document_product UNION ALL SELECT p.task_id, p.product_key, p.content_digest, p.release_id, p.contract_digest, body.descriptor -> 'content_metadata' ->> 'schema_digest', body.descriptor -> 'content_metadata' ->> 'recipe_digest', CAST(NULL AS bigint), CAST(NULL AS text), CAST(NULL AS text), b.content -> 'document', body.descriptor -> 'content_metadata' -> 'health', body.payload FROM ops.pdf_product AS p INNER JOIN ops.pdf_product_body AS body USING (task_id, product_key) CROSS JOIN LATERAL (SELECT CAST(CAST(convert_from(body.payload, 'UTF8') AS pg_catalog.json) -> 'content' AS jsonb) AS content) AS b WHERE p.kind = 'integrated';
CREATE OR REPLACE FUNCTION ops.integrated_source_context(p_task bigint, p_key text, p_digest text, p_pointers text[], p_section text, p_membership text) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'pg_catalog', 'pg_temp' AS $$
 WITH selected AS (
  SELECT o.* FROM kb.pdf_occurrence o WHERE o.task_id=p_task AND o.product_key=p_key AND o.pointer=ANY(p_pointers)
 ), relation_ids AS (
  SELECT DISTINCT e.relation_id FROM kb.pdf_relation_endpoint e JOIN selected o ON o.occurrence_id=e.occurrence_id
  WHERE e.task_id=p_task AND e.product_key=p_key AND e.target_task_id=p_task AND e.target_product_key=p_key
 ), related AS (
  SELECT r.* FROM kb.pdf_relation r JOIN relation_ids i USING(relation_id) WHERE r.task_id=p_task AND r.product_key=p_key
 ), endpoint_rows AS (
  SELECT e.* FROM kb.pdf_relation_endpoint e JOIN relation_ids i USING(relation_id) WHERE e.task_id=p_task AND e.product_key=p_key
 ), covered AS (
  SELECT c.* FROM kb.pdf_product_coverage c WHERE c.task_id=p_task AND c.product_key=p_key AND (
   c.body->>'scope' IN ('whole_document',p_section||':direct',p_section||':descendants') OR
   c.body->>'scope' IN (SELECT 'page:'||(o.body->>'page_no') FROM selected o UNION ALL SELECT 'pages:'||(o.body->>'page_no')||'-'||(o.body->>'page_no') FROM selected o)
  )
 ), input_rows AS (
  SELECT i.* FROM ops.pdf_product_input i WHERE i.task_id=p_task AND i.product_key=p_key AND (
   EXISTS(SELECT FROM endpoint_rows e WHERE e.role<>'output' AND (e.target_task_id,e.target_product_key,e.target_content_digest)=(i.input_task_id,i.input_product_key,i.input_content_digest)) OR
   i.input_index IN (SELECT (s->>'input_index')::bigint FROM covered c CROSS JOIN LATERAL jsonb_array_elements(COALESCE(c.body->'supports','[]')) s)
  )
 ) SELECT jsonb_build_object(
  'selection',jsonb_build_object('task_id',p.task_id,'product_key',p.product_key,'content_digest',p.content_digest),
  'descriptor',b.descriptor,
  'occurrences',COALESCE((SELECT jsonb_agg(to_jsonb(o) ORDER BY o.occurrence_id) FROM selected o),'[]'),
  'relations',COALESCE((SELECT jsonb_agg((to_jsonb(r)-'body')||jsonb_build_object('body',r.body-'endpoints','endpoints',COALESCE((SELECT jsonb_agg(to_jsonb(e) ORDER BY e.endpoint_index) FROM endpoint_rows e WHERE e.relation_id=r.relation_id),'[]')) ORDER BY r.relation_id) FROM related r),'[]'),
  'coverage',COALESCE((SELECT jsonb_agg(to_jsonb(c) ORDER BY c.coverage_id) FROM covered c),'[]'),
  'mapping_reports',COALESCE((SELECT jsonb_agg(to_jsonb(m) ORDER BY m.report_index) FROM kb.pdf_mapping_report m WHERE m.task_id=p_task AND m.product_key=p_key AND m.input_index IN (SELECT input_index FROM input_rows)),'[]'),
  'inputs',COALESCE((SELECT jsonb_agg(to_jsonb(i) ORDER BY i.input_index) FROM input_rows i),'[]')
 ) FROM ops.pdf_product p JOIN ops.pdf_product_body b USING(task_id,product_key)
 WHERE p.task_id=p_task AND p.product_key=p_key AND p.content_digest=p_digest AND p.kind='integrated'
$$;
REVOKE ALL PRIVILEGES ON FUNCTION ops.integrated_source_context (bigint, text, text, text[], text, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION ops.integrated_source_context (bigint, text, text, text[], text, text) TO corpus_sem_writer, corpus_sem_reader;
CREATE OR REPLACE FUNCTION ops.register_native_pdf(p_task bigint, p_key text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog', 'pg_temp' AS $$
DECLARE product ops.native_document_product; original text; value jsonb;
BEGIN
 SELECT * INTO STRICT product FROM ops.native_document_product WHERE task_id=p_task AND product_key=p_key;
 SELECT artifact_digest INTO STRICT original FROM ops.source_build WHERE task_id=p_task;
 INSERT INTO ops.pdf_product(task_id,product_key,content_digest,kind,artifact_digest,release_id,contract_digest)
 VALUES(p_task,p_key,product.content_digest,'native',original,product.release_id,product.contract_digest) ON CONFLICT DO NOTHING;
 IF NOT EXISTS(SELECT FROM ops.pdf_product WHERE task_id=p_task AND product_key=p_key AND content_digest=product.content_digest AND kind='native' AND artifact_digest=original AND release_id=product.release_id AND contract_digest=product.contract_digest) THEN
  RAISE EXCEPTION 'native common identity differs' USING ERRCODE='23514'; END IF;
 INSERT INTO ops.pdf_product_input(task_id,product_key,input_index,role,input_task_id,input_product_key,input_content_digest)
 SELECT p_task,p_key,0,'structural',product.parent_task_id,product.parent_product_key,product.parent_digest WHERE product.parent_task_id IS NOT NULL ON CONFLICT DO NOTHING;
 INSERT INTO kb.pdf_occurrence(task_id,product_key,occurrence_id,kind,address_space,precision,body,pointer)
 SELECT p_task,p_key,i.pointer,CASE WHEN i.label='formula' THEN 'formula' ELSE 'item' END,'native_item','item',
 jsonb_build_object('pointer',i.pointer,'native_value',i.native_json),i.pointer FROM kb.native_document_item i WHERE i.task_id=p_task AND i.product_key=p_key ON CONFLICT DO NOTHING;
 INSERT INTO kb.pdf_occurrence(task_id,product_key,occurrence_id,kind,address_space,precision,body,pointer)
 SELECT p_task,p_key,i.pointer||'/data/table_cells/'||(c.n-1)::text,'cell','native_cell','cell',jsonb_build_object('pointer',i.pointer,'cell_index',c.n-1,'native_value',c.value,'regions',i.native_json->'prov'),i.pointer
 FROM kb.native_document_item i CROSS JOIN LATERAL jsonb_array_elements(COALESCE(i.native_json->'data'->'table_cells','[]')) WITH ORDINALITY c(value,n)
 WHERE i.task_id=p_task AND i.product_key=p_key AND i.label='table' ON CONFLICT DO NOTHING;
 INSERT INTO kb.pdf_occurrence(task_id,product_key,occurrence_id,kind,address_space,precision,body,pointer)
 SELECT p_task,p_key,i.pointer||'/meta/tabular_chart/chart_data/table_cells/'||(c.n-1)::text,'cell','native_cell','inherited',jsonb_build_object('pointer',i.pointer,'cell_index',c.n-1,'native_value',c.value,'grounding_pointer',i.pointer,'regions',i.native_json->'prov'),i.pointer
 FROM kb.native_document_item i CROSS JOIN LATERAL jsonb_array_elements(COALESCE(i.native_json->'meta'->'tabular_chart'->'chart_data'->'table_cells','[]')) WITH ORDINALITY c(value,n)
 WHERE i.task_id=p_task AND i.product_key=p_key AND i.label='picture' ON CONFLICT DO NOTHING;
 INSERT INTO kb.pdf_occurrence(task_id,product_key,occurrence_id,kind,address_space,precision,body,pointer)
 SELECT p_task,p_key,pointer||'/prov/'||region_index::text,'region','pdf_points','item',to_jsonb(r),r.pointer FROM kb.native_document_region r WHERE r.task_id=p_task AND r.product_key=p_key ON CONFLICT DO NOTHING;
 -- Existing parent derivations keep their exact historical meaning; no recognizer is invented.
 INSERT INTO kb.pdf_relation(task_id,product_key,relation_id,kind,body)
 SELECT p_task,p_key,'native-derivation-'||mapping_index::text,'decision',jsonb_build_object('outcome','selected','policy','historical-native-derivation','mapping',to_jsonb(d))
 FROM kb.native_document_derivation d WHERE d.task_id=p_task AND d.product_key=p_key ON CONFLICT DO NOTHING;
 INSERT INTO kb.pdf_relation_endpoint(task_id,product_key,relation_id,endpoint_index,role,target_task_id,target_product_key,target_content_digest,occurrence_id)
 SELECT p_task,p_key,'native-derivation-'||d.mapping_index::text,0,'output',p_task,p_key,product.content_digest,d.pointer FROM kb.native_document_derivation d WHERE d.task_id=p_task AND d.product_key=p_key
 UNION ALL SELECT p_task,p_key,'native-derivation-'||d.mapping_index::text,1,'input',product.parent_task_id,product.parent_product_key,product.parent_digest,
 CASE WHEN d.cell_index IS NOT NULL THEN d.origin_pointer||'/data/table_cells/'||d.cell_index::text ELSE d.origin_pointer END
 FROM kb.native_document_derivation d WHERE d.task_id=p_task AND d.product_key=p_key ON CONFLICT DO NOTHING;
 INSERT INTO ops.pdf_product_artifact(task_id,product_key,artifact_digest) SELECT p_task,p_key,d FROM unnest(ARRAY[original,product.schema_digest,product.recipe_digest]) d ON CONFLICT DO NOTHING;
 value:=convert_from(product.payload,'UTF8')::jsonb;
 INSERT INTO kb.pdf_product_coverage(task_id,product_key,coverage_id,body)
 SELECT p_task,p_key,'native-'||family,jsonb_build_object('coverage_id','native-'||family,'scope',CASE WHEN jsonb_array_length(COALESCE(value->'health'->(family||'_scope'),'[]'))>0 THEN 'sections:'||(value->'health'->(family||'_scope'))::text||':'||(value->'health'->>(family||'_membership')) WHEN value->>'source_scope'='whole_document' THEN 'whole_document' ELSE 'pages:'||(value->>'page_start')||'-'||(value->>'page_end') END,'family',family,'outcome',value->'health'->>(family||'_coverage'),'discovery_policy',CASE family WHEN 'display' THEN 'detected-native-display-v1' WHEN 'inline' THEN COALESCE(value->'health'->>'candidate_policy','unknown') ELSE COALESCE(value->'health'->>'cells_policy','unknown') END,'detail','retained native health coverage') FROM unnest(ARRAY['display','inline','cell']) family ON CONFLICT DO NOTHING;
 INSERT INTO kb.pdf_product_coverage(task_id,product_key,coverage_id,body)
 SELECT p_task,p_key,'native-scoped-'||(n-1)::text,jsonb_build_object('coverage_id','native-scoped-'||(n-1)::text,'scope',(r->>'section_pointer')||':'||(r->>'membership'),'family',r->>'universe','outcome',r->>'outcome','discovery_policy',r->>'policy','detail','retained native scoped coverage') FROM jsonb_array_elements(COALESCE(value->'recognition_coverage','[]')) WITH ORDINALITY rows(r,n) ON CONFLICT DO NOTHING;
 INSERT INTO kb.pdf_product_coverage(task_id,product_key,coverage_id,body) VALUES(p_task,p_key,'native-health',value->'health') ON CONFLICT DO NOTHING;
END $$;
REVOKE ALL PRIVILEGES ON FUNCTION ops.register_native_pdf (bigint, text) FROM PUBLIC;
CREATE OR REPLACE FUNCTION ops.publish_integrated_pdf(p_task bigint, p_attempt bigint, p_holder text, p_contract text, p_payload bytea, p_artifacts bytea[]) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog', 'pg_temp' AS $$
DECLARE job ops.task; run ops.run; product jsonb:='{}'; parsing_item jsonb; selected_content jsonb; selected_document jsonb; digest text:=encode(sha256(p_payload),'hex');
 wire json; field_name text; field_value json; envelope_fields text[]:=ARRAY[]::text[];
 input_rows json; occurrence_rows json; relation_rows json; coverage_rows json; mapping_rows json;
 previous ops.pdf_product; input jsonb; occurrence jsonb; relation jsonb; endpoint jsonb; coverage jsonb; mapping_report jsonb; pin ops.pdf_product; idx bigint; eid bigint; original text; selected_node jsonb; selected_anchor jsonb; ancestor_pointer text; grounding_path text[];
BEGIN
 SELECT r.* INTO STRICT run FROM ops.run r JOIN ops.task t ON t.run_id=r.id WHERE t.id=p_task FOR SHARE OF r;
 SELECT * INTO STRICT job FROM ops.task WHERE id=p_task AND run_id=run.id FOR UPDATE;
 IF job.attempt<>p_attempt OR job.claimed_by IS DISTINCT FROM p_holder THEN RAISE EXCEPTION 'stale integrated PDF attempt' USING ERRCODE='P0004'; END IF;
 wire:=convert_from(p_payload,'UTF8')::json;
 IF json_typeof(wire) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'parsing record must be an object: PdfIntegratedProduct' USING ERRCODE='23514'; END IF;
 FOR field_name,field_value IN SELECT key,value FROM json_each(wire) LOOP
  envelope_fields:=array_append(envelope_fields,field_name);
  CASE field_name
   WHEN 'inputs' THEN input_rows:=field_value;
   WHEN 'occurrences' THEN occurrence_rows:=field_value;
   WHEN 'relations' THEN relation_rows:=field_value;
   WHEN 'coverage' THEN coverage_rows:=field_value;
   WHEN 'mapping_reports' THEN mapping_rows:=field_value;
   WHEN 'content' THEN
    selected_content:=field_value::jsonb;
    IF selected_content ? 'document_json' THEN RAISE EXCEPTION 'internal PDF content field supplied' USING ERRCODE='23514'; END IF;
    selected_document:=selected_content->'document';
    parsing_item:=(selected_content-'document')||jsonb_build_object('document_json',selected_document::text);
   ELSE product:=product||jsonb_build_object(field_name,field_value::jsonb);
  END CASE;
 END LOOP;
 IF jsonb_typeof(product) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'parsing record must be an object: PdfIntegratedProduct' USING ERRCODE='23514'; END IF;
IF EXISTS(SELECT FROM unnest(envelope_fields) key WHERE key<>ALL(ARRAY['mapping_reports','version','kind','product_key','artifact_digest','recipe_digest','inputs','occurrences','relations','coverage','health','observation','content'])) OR ('mapping_reports'=ANY(envelope_fields) AND (json_typeof(mapping_rows) IS DISTINCT FROM 'array')) OR NOT ('version'=ANY(envelope_fields)) OR ('version'=ANY(envelope_fields) AND (jsonb_typeof(product->'version') IS DISTINCT FROM 'number' OR product->>'version' !~ '^[0-9]+$')) OR ('version'=ANY(envelope_fields) AND (product->>'version')::numeric < 1) OR ('version'=ANY(envelope_fields) AND (product->>'version')::numeric > 1) OR NOT ('kind'=ANY(envelope_fields)) OR ('kind'=ANY(envelope_fields) AND (jsonb_typeof(product->'kind') IS DISTINCT FROM 'string' OR product->>'kind' NOT IN ('integrated','native','recognition_observation'))) OR NOT ('product_key'=ANY(envelope_fields)) OR ('product_key'=ANY(envelope_fields) AND (jsonb_typeof(product->'product_key') IS DISTINCT FROM 'string')) OR NOT ('artifact_digest'=ANY(envelope_fields)) OR ('artifact_digest'=ANY(envelope_fields) AND (jsonb_typeof(product->'artifact_digest') IS DISTINCT FROM 'string')) OR ('artifact_digest'=ANY(envelope_fields) AND product->>'artifact_digest' !~ '^[0-9a-f]{64}$') OR NOT ('recipe_digest'=ANY(envelope_fields)) OR ('recipe_digest'=ANY(envelope_fields) AND (jsonb_typeof(product->'recipe_digest') IS DISTINCT FROM 'string')) OR ('recipe_digest'=ANY(envelope_fields) AND product->>'recipe_digest' !~ '^[0-9a-f]{64}$') OR ('inputs'=ANY(envelope_fields) AND (json_typeof(input_rows) IS DISTINCT FROM 'array')) OR ('occurrences'=ANY(envelope_fields) AND (json_typeof(occurrence_rows) IS DISTINCT FROM 'array')) OR ('relations'=ANY(envelope_fields) AND (json_typeof(relation_rows) IS DISTINCT FROM 'array')) OR NOT ('coverage'=ANY(envelope_fields)) OR ('coverage'=ANY(envelope_fields) AND (json_typeof(coverage_rows) IS DISTINCT FROM 'array' OR json_array_length(coverage_rows) < 1)) OR NOT ('health'=ANY(envelope_fields)) OR ('health'=ANY(envelope_fields) AND (jsonb_typeof(product->'health') IS DISTINCT FROM 'object' OR (EXISTS(SELECT FROM jsonb_object_keys(product->'health') key WHERE key<>ALL(ARRAY['execution_outcome','mapping_outcome','source_fidelity','validation_report'])) OR NOT (product->'health' ? 'execution_outcome') OR (product->'health' ? 'execution_outcome' AND (jsonb_typeof(product->'health'->'execution_outcome') IS DISTINCT FROM 'string' OR product->'health'->>'execution_outcome' NOT IN ('failed','partial','succeeded','unknown','unsupported'))) OR NOT (product->'health' ? 'mapping_outcome') OR (product->'health' ? 'mapping_outcome' AND (jsonb_typeof(product->'health'->'mapping_outcome') IS DISTINCT FROM 'string' OR product->'health'->>'mapping_outcome' NOT IN ('coarse','partial','unknown','unsupported'))) OR NOT (product->'health' ? 'source_fidelity') OR (product->'health' ? 'source_fidelity' AND (jsonb_typeof(product->'health'->'source_fidelity') IS DISTINCT FROM 'string' OR product->'health'->>'source_fidelity' NOT IN ('conflict','unassessed','unknown'))) OR NOT (product->'health' ? 'validation_report') OR (product->'health' ? 'validation_report' AND (jsonb_typeof(product->'health'->'validation_report') IS DISTINCT FROM 'string'))))) OR ('observation'=ANY(envelope_fields) AND (jsonb_typeof(product->'observation') IS DISTINCT FROM 'object' OR (EXISTS(SELECT FROM jsonb_object_keys(product->'observation') key WHERE key<>ALL(ARRAY['binding','image','pass_role','raw_response_digest','finish_reason','usage_json','outcome','usage_availability','diagnostic'])) OR NOT (product->'observation' ? 'binding') OR (product->'observation' ? 'binding' AND (jsonb_typeof(product->'observation'->'binding') IS DISTINCT FROM 'object' OR (EXISTS(SELECT FROM jsonb_object_keys(product->'observation'->'binding') key WHERE key<>ALL(ARRAY['provider','package_identity','source_identity','weights_digest','tokenizer_digest','prompt_digest','decoding_json','see