  RAISE EXCEPTION 'native source scope differs' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM unnest(ARRAY['inline','cell']) universe WHERE product->'health'->>(universe||'_coverage')='complete' AND
